#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

int main() {
    int n, m;
    cin >> n >> m;

    vector<vector<int>> blockedColumns(n);
    for (int c = 0; c < m; ++c) {
        int row, column;
        cin >> row >> column;
        blockedColumns[row].push_back(column);
    }
    for (auto& row : blockedColumns) {
        sort(row.begin(), row.end());
    }

    vector<int> rowA(n, 0), rowB(n, 0);
    vector<int>* prev = &rowA;
    vector<int>* cur = &rowB;

    int running = 0;
    const vector<int>& firstRowBlocks = blockedColumns[0];
    auto block = firstRowBlocks.begin();
    for (int j = 0; j < n; ++j) {
        const bool isBlocked = block != firstRowBlocks.end() && *block == j;
        if (isBlocked) {
            running = 0;
            do {
                ++block;
            } while (block != firstRowBlocks.end() && *block == j);
        } else if (j == 0) {
            running = 1;
        }
        (*prev)[j] = running;
    }

    // Small grids avoid the synchronization cost of a parallel team.
    if (n < 4096) {
        for (int i = 1; i < n; ++i) {
            const vector<int>& obstacles = blockedColumns[i];
            auto obstacle = obstacles.begin();
            int prefix = 0;
            for (int j = 0; j < n; ++j) {
                const bool isBlocked = obstacle != obstacles.end() && *obstacle == j;
                if (isBlocked) {
                    prefix = 0;
                    (*cur)[j] = 0;
                    do {
                        ++obstacle;
                    } while (obstacle != obstacles.end() && *obstacle == j);
                } else {
                    prefix += (*prev)[j];
                    if (prefix >= MOD) prefix -= MOD;
                    (*cur)[j] = prefix;
                }
            }
            swap(prev, cur);
        }
    } else {
        const int chunks = min(4, n);
        vector<int> firstBlocked(chunks, -1);
        vector<int> localEnd(chunks, 0);
        vector<int> incoming(chunks, 0);

        // Each chunk computes a local segmented prefix. A short serial scan of
        // chunk summaries supplies the carry into each chunk; only values
        // before that chunk's first obstacle need the carry added afterward.
        #pragma omp parallel num_threads(4)
        {
            for (int i = 1; i < n; ++i) {
                const vector<int>& obstacles = blockedColumns[i];

                #pragma omp for schedule(static)
                for (int t = 0; t < chunks; ++t) {
                    const int lo = (n * t) / chunks;
                    const int hi = (n * (t + 1)) / chunks;
                    auto obstacle = lower_bound(obstacles.begin(), obstacles.end(), lo);
                    int prefix = 0;
                    int first = -1;

                    for (int j = lo; j < hi; ++j) {
                        const bool isBlocked = obstacle != obstacles.end() && *obstacle == j;
                        if (isBlocked) {
                            if (first == -1) first = j;
                            prefix = 0;
                            (*cur)[j] = 0;
                            do {
                                ++obstacle;
                            } while (obstacle != obstacles.end() && *obstacle == j);
                        } else {
                            prefix += (*prev)[j];
                            if (prefix >= MOD) prefix -= MOD;
                            (*cur)[j] = prefix;
                        }
                    }
                    firstBlocked[t] = first;
                    localEnd[t] = prefix;
                }

                #pragma omp single
                {
                    int carry = 0;
                    for (int t = 0; t < chunks; ++t) {
                        incoming[t] = carry;
                        if (firstBlocked[t] == -1) {
                            carry += localEnd[t];
                            if (carry >= MOD) carry -= MOD;
                        } else {
                            carry = localEnd[t];
                        }
                    }
                }

                #pragma omp for schedule(static)
                for (int t = 0; t < chunks; ++t) {
                    const int lo = (n * t) / chunks;
                    const int hi = (n * (t + 1)) / chunks;
                    const int stop = firstBlocked[t] == -1 ? hi : firstBlocked[t];
                    for (int j = lo; j < stop; ++j) {
                        int value = (*cur)[j] + incoming[t];
                        if (value >= MOD) value -= MOD;
                        (*cur)[j] = value;
                    }
                }

                #pragma omp single
                {
                    swap(prev, cur);
                }
            }
        }
    }

    cout << (*prev)[n - 1] << '\n';
    return 0;
}
